typedef struct {
    int index;
    void (*handler)();
} Payload;

Payload item = { 42, NULL };
Payload *item_ptr = &item;

// 1. Direct Access (Value or Reference)
int v1 = item.index;

// 2. Explicit Dereference and Access
// Precedence: . (dot) is higher than * (dereference).
// Parentheses are mandatory: (*ptr) before .
int v2 = (*item_ptr).index;

// 3. Arrow Operator (Syntactic Sugar for Explicit Access)
int v3 = item_ptr->index;

// Function pointer access
item_ptr->handler = /* function address */;
// Explicit dereference: (*item_ptr).handler();
item_ptr->handler();
